// Replaces o.R.OrcOrcamentoCompras with related.
// Sets related.R.EntEntidades's OrcOrcamentoCompras accordingly.
func (o *Entidade) SetOrcOrcamentoCompras(ctx context.Context, exec boil.ContextExecutor, insert bool, related ...*OrcamentoCompra) error {
	query := "delete from `orcamento_entidade` where `ent_id` = ?"
	values := []interface{}{o.EntID}
	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, query)
		fmt.Fprintln(writer, values)
	}
	_, err := exec.ExecContext(ctx, query, values...)
	if err != nil {
		return errors.Wrap(err, "failed to remove relationships before set")
	}

	removeOrcOrcamentoComprasFromEntEntidadesSlice(o, related)
	if o.R != nil {
		o.R.OrcOrcamentoCompras = nil
	}

	return o.AddOrcOrcamentoCompras(ctx, exec, insert, related...)
}

// RemoveOrcOrcamentoCompras relationships from objects passed in.
// Removes related items from R.OrcOrcamentoCompras (uses pointer comparison, removal does not keep order)
// Sets related.R.EntEntidades.
func (o *Entidade) RemoveOrcOrcamentoCompras(ctx context.Context, exec boil.ContextExecutor, related ...*OrcamentoCompra) error {
	if len(related) == 0 {
		return nil
	}

	var err error
	query := fmt.Sprintf(
		"delete from `orcamento_entidade` where `ent_id` = ? and `orc_id` in (%s)",
		strmangle.Placeholders(dialect.UseIndexPlaceholders, len(related), 2, 1),
	)
	values := []interface{}{o.EntID}
	for _, rel := range related {
		values = append(values, rel.OrcID)
	}

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, query)
		fmt.Fprintln(writer, values)
	}
	_, err = exec.ExecContext(ctx, query, values...)
	if err != nil {
		return errors.Wrap(err, "failed to remove relationships before set")
	}
	removeOrcOrcamentoComprasFromEntEntidadesSlice(o, related)
	if o.R == nil {
		return nil
	}

	for _, rel := range related {
		for i, ri := range o.R.OrcOrcamentoCompras {
			if rel != ri {
				continue
			}

			ln := len(o.R.OrcOrcamentoCompras)
			if ln > 1 && i < ln-1 {
				o.R.OrcOrcamentoCompras[i] = o.R.OrcOrcamentoCompras[ln-1]
			}
			o.R.OrcOrcamentoCompras = o.R.OrcOrcamentoCompras[:ln-1]
			break
		}
	}

	return nil
}

func removeOrcOrcamentoComprasFromEntEntidadesSlice(o *Entidade, related []*OrcamentoCompra) {
	for _, rel := range related {
		if rel.R == nil {
			continue
		}
		for i, ri := range rel.R.EntEntidades {
			if o.EntID != ri.EntID {
				continue
			}

			ln := len(rel.R.EntEntidades)
			if ln > 1 && i < ln-1 {
				rel.R.EntEntidades[i] = rel.R.EntEntidades[ln-1]
			}
			rel.R.EntEntidades = rel.R.EntEntidades[:ln-1]
			break
		}
	}
}

